message.content:
{
  "title": "The Gilded Gauntlet",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "A massive iron gate hangs crooked on broken hinges; the city wall is cracked and overgrown with thorny vines.",
      "characters": ["Kaelen", "Mira", "Torvin"]
    },
    {
      "scene_number": 2,
      "caption": "Townspeople flee past an old royal banner.",
      "visual_description": "Tattered gold-and-crimson banner droops from a collapsed archway; frightened citizens run clutching bundles.",
      "characters": ["Kaelen", "Mira", "Torvin", "Fleeing Townsfolk"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrol questions the party's intent.",
      "visual_description": "Three helmeted soldiers in rusted plate armor block the street, halberds crossed.",
      "characters": ["Kaelen", "Mira", "Torvin", "City Patrol"]
    },
    {
      "scene_number": 4,
      "caption": "A cursed tower looms at the square's center.",
      "visual_description": "A spiraling black tower with glowing runes pulses above the cobblestone plaza.",
      "characters": ["Kaelen", "Mira", "Torvin"]
    },
    {
      "scene_number": 5,
      "caption": "Rumors of a dragon stir in a crowded tavern.",
      "visual_description": "Smoky tavern interior; a hooded figure whispers to the party while patrons huddle nervously.",
      "characters": ["Kaelen", "Mira", "Torvin", "Whispering Informant", "Tavern Patrons"]
    },
    {
      "scene_number": 6,
      "caption": "The party enters a magic door that shifts location.",
      "visual_description": "A stone doorway framed with shifting silver sigils; beyond it a corridor that appears to bend sideways.",
      "characters": ["Kaelen", "Mira", "Torvin"]
    },
    {
      "scene_number": 7,
      "caption": "Inside the cursed tower: first temptation.",
      "visual_description": "A floating golden crown bathes the room in warm light; the floor is mosaic of pleading faces.",
      "characters": ["Kaelen", "Mira", "Torvin"]
    },
    {
      "scene_number": 8,
      "caption": "Mira resists the crown's illusion of power.",
      "visual_description": "Mira turns her back on the crown, hand on her sword; the crown's glow flickers angrily.",
      "characters": ["Mira"]
    },
    {
      "scene_number": 9,
      "caption": "Torvin breaks a cursed mirror showing lost family.",
      "visual_description": "A tall silver mirror shows Torvin's dead wife smiling; he shatters it with his axe.",
      "characters": ["Torvin"]
    },
    {
      "scene_number": 10,
      "caption": "Kaelen ignores a spectral vision of glory.",
      "visual_description": "A ghostly king offers Kaelen a scepter; Kaelen steps past without looking back.",
      "characters": ["Kaelen", "Spectral King"]
    },
    {
      "scene_number": 11,
      "caption": "The party reunites on the tower's upper floor.",
      "visual_description": "A circular room with three open doors; each door frames one of the party members entering from different directions.",
      "characters": ["Kaelen", "Mira", "Torvin"]
    },
    {
      "scene_number": 12,
      "caption": "They find the captive in a crystal prison.",
      "visual_description": "A young woman suspended inside a hexagonal crystal, eyes closed, hands pressed against the inner facet.",
      "characters": ["Kaelen", "Mira", "Torvin", "Captive Princess"]
    },
    {
      "scene_number": 13,
      "caption": "The tower awakens: stone golems rise.",
      "visual_description": "Four massive golems of black stone and rune-etched iron rise from the floor tiles.",
      "characters": ["Kaelen", "Mira", "Torvin", "Stone Golems"]
    },
    {
      "scene_number": 14,
      "caption": "Battle in the tower's central hall.",
      "visual_description": "Sparks fly as Mira's blade meets golem fist; Torvin swings his axe; Kaelen fires an arrow into a rune.",
      "characters": ["Kaelen", "Mira", "Torvin", "Stone Golems"]
    },
    {
      "scene_number": 15,
      "caption": "The party frees the princess and flees downward.",
      "visual_description": "Crystal shatters; the princess falls into Torvin's arms; behind them the floor crumbles.",
      "characters": ["Kaelen", "Mira", "Torvin", "Captive Princess"]
    },
    {
      "scene_number": 16,
      "caption": "Chased through the city streets to the bridge.",
      "visual_description": "The party sprints across rubble-strewn lanes, golems and patrols closing behind them.",
      "characters": ["Kaelen", "Mira", "Torvin", "Captive Princess", "Stone Golems", "City Patrol"]
    },
    {
      "scene_number": 17,
      "caption": "Last stand on the damaged bridge.",
      "visual_description": "A stone bridge missing half its arch; fire spouts from beneath; the party turns to face the pursuing horde.",
      "characters": ["Kaelen", "Mira", "Torvin", "Captive Princess", "Stone Golems", "City Patrol"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses and the party escapes.",
      "visual_description": "The bridge falls into the chasm; the party clutches the far edge, silhouetted against a dawn sky.",
      "characters": ["Kaelen", "Mira", "Torvin", "Captive Princess"]
    }
  ]
}

